/** One ER visit — GET /api/v1/er/visits/{er_visit_id} (who may call: holders of er.visit.view). */
export function getVisit(er_visit_id: number): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("GET", `/er/visits/${er_visit_id}`, undefined);
}

/** The triage scale and its algorithm — GET /api/v1/er/triage-scale (who may call: holders of er.visit.view). */
export function getScale(query?: { include_inactive?: boolean }): Promise<ErTriageScaleOut> {
  return api<ErTriageScaleOut>("GET", withQuery(`/er/triage-scale`, query), undefined);
}

/** Triage (or re-triage) the patient — POST /api/v1/er/visits/{er_visit_id}/triage (who may call: holders of er.triage.record). */
export function triageVisit(er_visit_id: number, body: ErTriageIn): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("POST", `/er/visits/${er_visit_id}/triage`, body, { idempotent: true });
}

/** Answer or correct the medico-legal checklist — POST /api/v1/er/visits/{er_visit_id}/medico-legal (who may call: holders of er.triage.record). */
export function medicoLegal(er_visit_id: number, body: ErMedicoLegalIn): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("POST", `/er/visits/${er_visit_id}/medico-legal`, body, { idempotent: true });
}

/** Move the patient to treatment, observation or waiting for a referral — POST /api/v1/er/visits/{er_visit_id}/stage (who may call: holders of er.visit.manage). */
export function setStage(er_visit_id: number, body: ErStageIn): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("POST", `/er/visits/${er_visit_id}/stage`, body, { idempotent: true });
}

/** Record how the patient left the emergency department — POST /api/v1/er/visits/{er_visit_id}/depart (who may call: holders of er.visit.manage). */
export function depart(er_visit_id: number, body: ErDepartIn): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("POST", `/er/visits/${er_visit_id}/depart`, body, { idempotent: true });
}

/** Medico-legal case types — GET /api/v1/mlc/case-types (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function caseTypes(query?: { include_inactive?: boolean }): Promise<MlcCaseTypeOut[]> {
  return api<MlcCaseTypeOut[]>("GET", withQuery(`/mlc/case-types`, query), undefined);
}

/** Open a medico-legal case — POST /api/v1/mlc/cases (who may call: holders of mlc.case.manage). */
export function openCaseMlcCases(body: MlcOpenIn): Promise<MlcCaseOut> {
  return api<MlcCaseOut>("POST", `/mlc/cases`, body, { idempotent: true });
}

